func _init() -> void:
	_run.call_deferred()


func _run() -> void:
	var cam := Camera3D.new()
	root.add_child(cam)
	cam.position = Vector3(0.0, 7.0, 9.0)
	cam.look_at(Vector3.ZERO, Vector3.UP)
	cam.current = true
	var layer := CanvasLayer.new()
	root.add_child(layer)
