	await process_frame
	await process_frame
	var vp: Vector2 = view.size
	print("view_size=", vp)
	var plates: Array = []
	for ch in view.get_children():
		if ch is Panel:
			plates.append(ch)
	print("plates=", plates.size())
	for i in range(plates.size()):
		var p: Panel = plates[i]
		var world: Vector3 = entries[i]["world"] + Vector3(0.0, 0.06, 0.0)
		var behind: bool = cam.is_position_behind(world)
		var sp: Vector2 = cam.unproject_position(world)
		var anchor_pt: Vector2 = p.position + Vector2(p.size.x * 0.5, p.size.y)
		var in_bounds: bool = p.position.x >= 7.0 and p.position.y >= 200.0 \
				and p.position.x + p.size.x <= vp.x - 7.0 and p.position.y + p.size.y <= vp.y - 95.0
		print("plate", i, " behind=", behind, " visible=", p.visible,
				" size=", p.size, " pos=", p.position, " screen_pt=", sp,
				" anchor_delta=", (anchor_pt - sp).abs(), " in_bounds=", in_bounds)
	print("hint_visible=", view.get_child(view.get_child_count() - 1).visible)
	print("SMOKE OK")
	quit(0)
